            <div class="eng-stat-item"><div class="eng-stat-number">${todayStats.copies}</div><div class="eng-stat-label">📝 抄写</div><div class="eng-mini-bar"><div class="eng-mini-fill" style="width:${bar(todayStats.copies, 10)}"></div></div></div>
